using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.JournalEntries.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.JournalEntries.Commands.AddJournalEntryLine;public sealed class AddJournalEntryLineCommandHandler(IJournalEntryRepository repository,IAccountRepository accounts,IApplicationDbContext db):IRequestHandler<AddJournalEntryLineCommand,Result<JournalEntryLineDto>>{public async Task<Result<JournalEntryLineDto>>Handle(AddJournalEntryLineCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.JournalEntryId,cancellationToken);if(e is null)return Result.Failure<JournalEntryLineDto>(JournalEntryErrors.NotFound);if(e.Status!="Draft")return Result.Failure<JournalEntryLineDto>(JournalEntryErrors.NotDraft);var account=await accounts.FindByIdAsync(request.AccountId,cancellationToken);if(account is null||!account.IsActive||!account.IsPostingAllowed)return Result.Failure<JournalEntryLineDto>(JournalEntryErrors.AccountNotPosting);var line=e.AddLine(request.AccountId,request.Debit,request.Credit,request.BranchId,request.CostCenterId,request.ProjectId,request.Description);await db.SaveChangesAsync(cancellationToken);return Result.Success(JournalEntryLineDto.FromEntity(line));}}
